'use strict';

// MODULES //

var objectKeys = require( '@stdlib/utils/keys' );
var anchorPositions = require( '@stdlib/plot/vega/base/anchor-positions' );
var anchorFrames = require( '@stdlib/plot/vega/base/anchor-reference-frames' );
var verticalBaselines = require( '@stdlib/plot/vega/base/vertical-baselines' );
var orientations = require( '@stdlib/plot/vega/title/orientations' );


// VARIABLES //

var ALIGNMENTS = [ // FIXME: use package rather than hardcode
	'',
	'left',
	'right',
	'center'
];
var ANCHORS = [ '' ].concat( anchorPositions() );
var ANCHOR_FRAMES = [ '' ].concat( anchorFrames() );

var BASELINES = [ '' ].concat( verticalBaselines() );

var FONT_WEIGHTS = [ // FIXME: use package rather than hardcode
	'',
	'normal',
	'bold',
	'lighter',
	'bolder',
	'100',
	'200',
	'300',
	'400',
	'500',
	'600',
	'700',
	'800',
	'900'
];

var ORIENTATIONS = [ '' ].concat( orientations() );


// MAIN //

/**
* Adds a "general" menu to an editor.
*
* @private
* @param {Editor} editor - editor instance
* @param {Object} conf - editor configuration
* @returns {Controller} menu controller
*/
function addMenu( editor, conf ) {
	var folder;
	var keys;
	var k;
	var i;

	keys = objectKeys( conf );
	if ( keys.length === 0 ) {
		return;
	}
	folder = editor.addFolder( 'Title' );
	folder.close();

	// TODO: consider refactoring to a hash look-up table where the values are one-liner functions
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		if ( k === 'align' ) {
			folder.add( conf, k, ALIGNMENTS );
		} else if ( k === 'anchor' ) {
			folder.add( conf, k, ANCHORS );
		} else if ( k === 'angle' ) {
			folder.add( conf, k, 0, 360 );
		} else if ( k === 'baseline' ) {
			folder.add( conf, k, BASELINES );
		} else if ( k === 'color' ) {
			folder.addColor( conf, k );
		} else if ( k === 'dx' ) {
			folder.add( conf, k );
		} else if ( k === 'dy' ) {
			folder.add( conf, k );
		} else if ( k === 'font' ) {
			folder.add( conf, k );
		} else if ( k === 'fontSize' ) {
			folder.add( conf, k ).min( 0 ).step( 1 );
		} else if ( k === 'fontStyle' ) {
			folder.add( conf, k );
		} else if ( k === 'fontWeight' ) {
			folder.add( conf, k, FONT_WEIGHTS );
		} else if ( k === 'frame' ) {
			folder.add( conf, k, ANCHOR_FRAMES );
		} else if ( k === 'limit' ) {
			folder.add( conf, k ).min( 0 );
		} else if ( k === 'lineHeight' ) {
			folder.add( conf, k ).min( 0 );
		} else if ( k === 'offset' ) {
			folder.add( conf, k );
		} else if ( k === 'orient' ) {
			folder.add( conf, k, ORIENTATIONS );
		} else if ( k === 'subtitle' ) {
			folder.add( conf, k );
		} else if ( k === 'subtitleColor' ) {
			folder.addColor( conf, k );
		} else if ( k === 'subtitleFont' ) {
			folder.add( conf, k );
		} else if ( k === 'subtitleFontSize' ) {
			folder.add( conf, k ).min( 0 ).step( 1 );
		} else if ( k === 'subtitleFontStyle' ) {
			folder.add( conf, k );
		} else if ( k === 'subtitleFontWeight' ) {
			folder.add( conf, k, FONT_WEIGHTS );
		} else if ( k === 'subtitleLineHeight' ) {
			folder.add( conf, k ).min( 0 ).step( 1 );
		} else if ( k === 'subtitlePadding' ) {
			folder.add( conf, k );
		} else if ( k === 'text' ) {
			folder.add( conf, k );
		} else {
			console.log( 'Unrecognized property in editor configuration. Key: %s.', k );
		}
	}
	return folder;
}


// EXPORTS //

module.exports = addMenu;
